sessions.push(...[{"number":24,"id":"Ej08aGix_h0","url":"https://www.youtube.com/watch?v=Ej08aGix_h0","type":"other","type_he":"תוכן נוסף","duration":"1:34 דקות","title_he":"סרטון סיכום הכנס בלונדון","speaker_he":"","summary":"לפריט זה אין תמלול ולכן לא נכתב לו תוכן. הוא נשאר ברשימת הסשנים כדי להראות את הקישור למקור ואת הפער בגלוי.","takeaways":[],"category":"תוכן נוסף","coverage":"כל התמליל הזמין נסקר. URL מדויק נמצא, אך אין גוף תמלול. לא הושלם מידע מתיאור, כותרת או הרצאות אחרות. אין להציג כהרצאה עצמאית או כסיכום שנכתב מצפייה. יש להציג שאין תמלול במקור שנבדק.","source_basis":"פריט המקור מכיל רק את עמוד YouTube (כותרת, קישורי תחתית וזכויות יוצרים של Google, תאריך 2026-06-02). אין תמלול של הסרטון.","lead":"סרטון סיכום: אין טקסט זמין, ולכן אין תוכן להצגה","chapters":[],"diagram":null,"terms":[],"gaps":["אין תמלול או תיאור של תוכן הסרטון; המקור הכיל רק דף YouTube. לא נטען שהסרטון נצפה.","אין לכתוב סיכום מומצא לפריט זה. אפשר להציג בלבד קישור ושם, או לבדוק אם במאגר הרשמי יש טקסט מתאים (לא נמצא בחבילה שנבדקה עבור פריט זה)."],"source_refs":["https://www.youtube.com/watch?v=Ej08aGix_h0"]},{"number":25,"id":"pyYKOLEnsZk","url":"https://www.youtube.com/watch?v=pyYKOLEnsZk","type":"session","type_he":"סשן","duration":"35:22 דקות","title_he":"להמציא מחדש את צוות הפיתוח","speaker_he":"האנה פוקסוול","summary":"האנה פוקסוול, יועצת עצמאית וכותבת, מדברת לא על כלים אלא על ארגון צוותים כשמהירות הפיתוח כבר כאן. היא מציגה שלושה עוגנים ('דברים שאני מאמינה שיישארו נכונים בלי קשר לטיב הסוכנים') ובכל אחד מפרידה בין מה שהיא שומרת, זורקת ומנסה.","takeaways":["המהירות יוצרת לחץ על החלטות מוצר. אבטיפוס זול מאפשר אימות רעיון, אבל בניית כל בקשה פוגעת בקוהרנטיות ובשימושיות.","לנסות קירוב מהנדסים ללקוחות, Product Engineers או Forward-Deployed Engineers וצוותים קטנים. היחסים המספריים המוזכרים הם ניסויים ותצפיות, לא נוסחת כוח אדם.","למפות את הדרך לייצור ולתקן צווארי בקבוק בבדיקות, ביקורת ופריסה. אפשר להפנות חלק מהצוות לתשתית ולבדיקות במקום לעוד פיצ׳רים.","Feature Flags, מסירה הדרגתית, SLIs, SLOs ותקציבי שגיאה מאפשרים שיח על מהירות מול אמינות. אבטחה ואמינות הן ציפיות לקוח גם ללא בקשת פיצ׳ר.","היא מציעה להעביר חלק מביקורת העמיתים להחלטות ולמפרט, במקום להניח שכל שינוי גדול ניתן לביקורת שורתית. זו עמדה לבחינה, לא ויתור על הבטחת איכות.","גודל צוות נדרש לתמוך בכוננות הוגנת ובעלות על ייצור. דוגמת ארבעה אנשים מניחה ראשי ומשני ועד 50% כוננות; היא אינה כלל אוניברסלי. מומלץ לפתח עומק בכמה תחומים ואמפתיה למשתמש."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. יש גוף הרצאה וסיכום. הדוברת מפנה לשאלות בהמשך על בירה. אין מקטע שאלות בתמלול ומילות הסיום של המנחה נחתכות. אין להצהיר שסוקר כל הווידאו. ביטול ביקורת חובה לכל שינוי הוא עמדה של הדוברת, לא המלצת ברירת מחדל לסביבה מפוקחת.","source_basis":"תמלול מלא שסופק (קובץ מקור 4, פריט 5), כולל תודות המנחה בפתיחה. אין שאלות ותשובות בסוף התמלול. תמלול אוטומטי עם שגיאות.","lead":"שלוש עוגנים לתכנון צוותים בעידן הסוכנים: לבנות משהו ששווה לבנות, מהירות דורשת בטיחות, ואנשים חשובים","chapters":[{"title":"הרקע: מהירות שנחלמה והגיעה","body":["מאז שהיא עובדת בטכנולוגיה, כל מנהל רצה יותר velocity (שנמדד אפילו ב-story points). לדבריה זה כבר כאן ומשנה הכול. כמו בטרנספורמציית הענן והמעבר ל-DevOps, כל שינוי כזה מביא אתגרים ארגוניים חדשים. היא אומרת שהדיבור על חוויית מפתח ופרודוקטיביות 'שקט' כי קיבלו את המהירות ולא יודעים מה לעשות בה.","היא מציגה שקף של רמות הבשלות של קידוד סוכני (שהיא 'גנבה' מלוק מרסדן, מרצה אחר בכנס), שבסולם עד רמה 8, מתזמר סוכנים כמו Gas Town. לדבריה אין בעיה להיות ברמה 2 או 3, והיא לא מכירה אף אחד שיכול לטעון בביטחון שהוא עובד ברמה 8 בבטחה. היא מזכירה פוסט של Cursor על 'העידן השלישי' שבו משימות סוכניות עוקפות השלמות tab."],"points":[],"kind":"idea"},{"title":"עוגן 1: לבנות משהו ששווה לבנות","body":["תמיד צריך לרדוף אחרי התוצאה ולא אחרי המשימה: הקוד הוא האיך, לא המה. בארגון אופייני יש משתמשים עם בעיות, מנהל מוצר שמסנן אותן לדרישות, ומפתחים שמספקים. מנהל המוצר מחליט מה לא לבנות, וזה לא משתנה. מה שהשתנה הוא הקצב: היא רואה 'לחץ אחורי' (back pressure) במוצר, כי קצב קבלת ההחלטות והניתוח לא עומד בקצב הפיתוח. 'להגיד כן לכל דבר' ייצור מוצר מנופח ויפגע בחוויה.","מה שחדש: זול יותר לבדוק רעיונות עם אב-טיפוס אמיתי. בעבר, כשהייתה לה בעיה בצד המוצר עם בקלוג של שלוש שנים, קשה היה להצדיק אב-טיפוס."],"points":[],"kind":"idea"},{"title":"דפוסי צוות שהיא רואה","body":["על גודל הצוות: צוות 'נורמלי' של 6 עד 8 מהנדסים ו-PM אחד נראה לה לא מאוזן ומייצר צוואר בקבוק בהחלטות. היא מזכירה ניסויים ביחס 2 מפתחים ל-PM אחד (אצל חברה בשם NPM, לדבריה) ואת דברי אנדרו נג בדאבוס שהצוות עשוי להיראות כשני אנשי מוצר למפתח אחד (כפי שהיא מדווחת). בשיחה עם CTO של חברת ייעוץ שמעה שלא מצמצמים צוותים אלא מצפים ליותר תפוקה; רק שניים או שלושה צמצמו בכוונה."],"points":["Vibe coding product manager: מנהל מוצר בונה אב-טיפוס בעצמו, והעבודה שמגיעה למפתחים כבר מאומתת.","מפתחים פונים החוצה: אם PM לא נוח עם אב-טיפוס, מפתחים חוקרים יחד איתו לפני העבודה על הפקה.","Forward deployed engineer: לא מהנדס מכירות או ארכיטקט פתרונות, אלא מהנדס מועצם שיושב ליד המשתמשים ומתקן את המוצר. היא מציינת שגוגל הכריזה לפני כמה שבועות על יכולת כזו.","Product engineer: מהנדסים שאינם צריכים אישור PM לשפר מוצר (היא מפנה לכתיבה של incident.io), במיוחד כשמפתחים בונים כלים למפתחים."],"kind":"idea"},{"title":"הניסיון האישי: מוצר בשני אנשים","body":["היא בונה כעת, עם שותף אחד, פלטפורמה לניהול base images של קונטיינרים, בהשערה ש-zero-CVE base images יהפכו לנורמה. יחס 1:1 של מפתח לאיש מוצר. נתנו לעצמם שבועיים לבנות MVP. ביום הראשון סיימו עד הצהריים, ובדרך לרכבת קיבלה הודעה 'done' ב-11 בבוקר. 'מה אם עבודה הייתה רק בין 9 ל-11?'.","היא למדה שהמהירות מגדילה שאפתנות, צריך לזרוק חלק מארגז הכלים של המוצר (תעדוף אכזרי, פרוס פיצ'רים), ולחשוב רחוק יותר. הם בדקו את הרעיון ב-KubeCon, התקבל היטב, והחליטו להשקיע. היא ציינה שלא היה צריך 'לדפוק בדלת של VC': אפשר לבנות ולבדוק."],"points":[],"kind":"idea"},{"title":"מה שומרת, זורקת ומנסה (עוגן 1)","body":"","points":["שומרת: צוותי מוצר מועצמים, משוב מהיר ממשתמשים אמיתיים, הבנת הבעיה. כשכולם יכולים לבנות מהר, חוויית משתמש ושימושיות הם המבדל.","זורקת: 'צוות שתי פיצות' ומפת דרכים של שישה חודשים. היא אוהבת את ההצעה לקרוא לצוות 'teeny tiny tapas team'.","מנסה: מודל forward deployed engineer, product engineers, אב-טיפוס מהיר ו'להיכשל מהר', צוותים קטנים ויחס נכון בין מפתחים לאנשי מוצר."],"kind":"idea"},{"title":"עוגן 2: מהירות דורשת בטיחות","body":["מסלול ההגעה לפרודקשן הוא המבדל. אם יש צעדים ידניים (סקירות קוד, בדיקות) יהיה 'פקק' במקום אחר. 'ביטחון גבוה דורש בדיקות, וביטחון גבוה במהירות דורש אוטומציה'. היא מזכירה פוסט של AWS שבו נאלצו לחשוב מחדש על המסלול, ומקרה של JP Morgan על בדיקות רכיבים רציפות בעזרת AI, וש-AI מצוין בכתיבת בדיקות. אפשר לפצל חלק מהצוות לטובת pipelines וכיסוי בדיקות.","היא מזכירה שעלות התחזוקה והשינוי עולה בהרבה מגרסה ראשונה. משתמשים לא מבקשים 'אל תשלחו חולשות' אבל מצפים לכך: 'אבטחה טובה בלתי נראית, אבטחה רעה הורגת מוניטין'. בעבר היה צריך להתמקח על זמן ב-backlog; כעת אפשר לנסות לעשות הכול."],"points":[],"kind":"idea"},{"title":"פרקטיקות: Progressive delivery, SRE ופלטפורמה","body":["Progressive delivery: feature flags שמפרידים מסירת פיצ'ר מפריסה, ו-blue/green שבו משחרר גרסה לחלק מהמשתמשים. SRE: SLIs ו-SLOs וגם error budgets כשפה לשוחח על האם להאט את קצב השינוי. היא רואה עתיד שבו צוותי פלטפורמה ו-SRE (כיועצים פנימיים) חשובים עוד יותר.","בניסיון שלה, אחרי שבועיים של MVP, העבודה נראתה כמו הנדסת פלטפורמה ואמינות: סקלביליות ואבטחה, לא פיצ'רים. היא מצפה שהיחס בין צוותי פיצ'רים לצוותי פלטפורמה/SRE/אבטחה ישתנה."],"points":[],"kind":"idea"},{"title":"מה שומרת, זורקת ומנסה (עוגן 2)","body":"","points":["שומרת: פרקטיקות SRE, progressive delivery ופלטפורמות פנימיות.","זורקת: כל צעד ידני על המסלול הקריטי לפרודקשן (בדיקות ידניות יכולות להיות מחוץ לו), ובטיחות באמצעות feature flags גם אם ספק באגים.","מנסה: טיפול בחוב טכני עם AI, שיפור כיסוי בדיקות, האצת מיגרציות ורפקטורים, והחזרת SRE כיועצים פנימיים."],"kind":"idea"},{"title":"עוגן 3: אנשים חשובים","body":["היא טוענת (באופן שנוי במחלוקת, כדבריה) שסקירת אלפי שורות קוד שנכתבו על ידי AI אינה משימה כיפית. כמה ארגונים הצהירו שאין סקירת קוד חובה לכל שינוי, וחלקם מעבירים את סקירת העמיתים שמאלה אל כתיבת המפרט לסוכן. היא מצטטת את ג'וזף רוסיה (בתמלול): 'הטעות היא להתייחס לקוד שלא נקרא ככישלון משמעת ולא כסימן שהמשמעת עצמה חייבת להשתנות'.","תורנות on-call: סוכן לא יכול לקבל התראה. צריך מחזור on-call בר-קיימא, עם ראשי ומשני ולא יותר מ-50% מהזמן. לכן 'המינימום האנושי' נקבע במידה רבה על ידי יכולת לתמוך בשירות. היא מציעה לאתגר טקסים כמו תכנון ספרינט של שבועיים, ומציעה לצפות בהרצאה של סופי ווסטון ב-QCon על 'מסרק שבור' (broken comb) במקום T-shaped: אנשים עם כמה תחומי עומק, כולל נטייה לצד המוצר או הפלטפורמה."],"points":[],"kind":"idea"},{"title":"מה שומרת, זורקת ומנסה (עוגן 3) וסיכום","body":["הסיום: 'ניסו עם אמפתיה: חשוב לשתף למידה אבל לעשות זאת עם אנשים, לא להם'."],"points":["שומרת: תורנויות on-call בר-קיימא, שפה לדיון ב-error budgets ויעדי זמינות, תכנון קריירה לכישורי היום.","זורקת: תכנון כבד, ספרינטים של שבועיים (ארוכים מדי לדבריה), סקירת קוד חובה לכל שינוי.","מנסה: shift left של סקירת עמיתים באמצעות spec-driven development, ועידוד אנשים ל'מסרק שבור'. היא מדגישה אמפתיה למשתמשים כמיומנות קריטית, ושלא להיות 'מאכילים בכפית'."],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["צוותים צריכים לשנות מבנה כשהקוד זול, והחסם עובר להחלטות ולבטיחות.","מסלול אוטומטי לפרודקשן ו-SRE הם תנאי לקצב.","התכנון צריך לשקול עומס אנושי ו-on-call, לא רק יעילות."],"kind":"idea"}],"diagram":{"kind":"anchors","title":"שלושת העוגנים של האנה","nodes":[{"id":"a","label":"1. לבנות משהו ששווה לבנות (תוצאה על פני משימה)"},{"id":"b","label":"2. מהירות דורשת בטיחות (pipeline, SRE, progressive delivery)"},{"id":"c","label":"3. אנשים חשובים (on-call, סקירה, כישורים, אמפתיה)"}],"edges":[{"from":"a","to":"b","label":"מהירות יותר"},{"from":"b","to":"c","label":"עומס אנושי"}],"caption":"בכל עוגן: שומרת, זורקת, מנסה."},"terms":[{"term":"Back pressure במוצר","definition":"קצב הפיתוח מהיר מקצב ההחלטות והניתוח."},{"term":"Forward deployed engineer","definition":"מהנדס מועצם שיושב ליד המשתמשים ומתקן את המוצר."},{"term":"Product engineer","definition":"מהנדס שמשפר מוצר בלי אישור PM."},{"term":"Progressive delivery","definition":"שחרור הדרגתי באמצעות feature flags ו-blue/green."},{"term":"Broken comb","definition":"מושג מהרצאה אחרת: אדם עם כמה תחומי עומק במקום T-shape אחד."}],"gaps":["אין שאלות ותשובות בתמלול.","שמות אנשים וחברות מתומללים באופן לא ודאי (NPM, Joseph Russia, Sophie Weston).","היא מציגה שקפים שאינם זמינים בתמלול.","הדוגמאות על NPM, אנדרו נג, CTO של חברת ייעוץ וג'וזף רוסיה הן דברי הדוברת בלבד ושמות רבים משובשים בתמלול.","האנקדוטה על 'סיימנו ב-11 בבוקר' היא חוויה אישית של שני אנשים."],"source_refs":["https://www.youtube.com/watch?v=pyYKOLEnsZk"]},{"number":26,"id":"I9RWrW32QEw","url":"https://www.youtube.com/watch?v=I9RWrW32QEw","type":"session","type_he":"סשן","duration":"30:48 דקות","title_he":"לאפשר לסוכנים לעבוד: לאפשר לסוכנים ולצוותים להשתפר בקנה מידה","speaker_he":"פטריק דבואה","summary":"פטריק דבואה (AI Product Engineer ב-Tessl, אוצר AINativeDev.io, ומי שמזוהה עם תחילת DevOps) מציג הרצאה חדשה לגמרי שנכתבה בכנס עצמו. הוא מתאר את הצורך בתפקיד 'Agent Enablement' בארבע שכבות: הסוכן, הצוות, הפלטפורמה והארגון.","takeaways":["כשסוכן טועה, לשאול מה לשנות במפרט, בכלי, בבדיקה או בתשתית כדי שלא יחזור על הטעות. תיקון ידני אינו שיפור של המערכת.","צוות צריך ספריית הקשר משותפת, מפרטים מתוחזקים ובעלות. ריבוי הגדרות אישיות ו-Harnesses הוא שלב ניסוי, לא בהכרח מודל תחזוקה.","למדוד סבבי תיקון, עבודה חוזרת ואיכות, לא רק מהירות וטוקנים. ברטרוספקטיבה בודקים גם איך הסוכנים עבדו ומה חסר להם.","פלטפורמה יכולה לספק רישום גרסאות, שירות עצמי, הערכות ותצפית. רכיבים משותפים צריכים בעלים, תקציב ותחזוקה.","לסגור משוב מהייצור למערכת הפיתוח. חיבור הרשאות בין מערכות ארגוניות אינו נפתר בפרומפט טוב.","הנהלה מאזנת קצב בין צוותים, מממנת הכשרה ובקרה והופכת תועלת למדידה. אוטומציה בלי ממשל משאירה את החוליה החלשה פתוחה."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. התמלול מגיע לסיכום ולתודה. אין שאלות או מעבר מנחה שמאפשר לאמת את סיום כל הווידאו. הדובר מגדיר את ההרצאה כניסיונית ומדגיש שאין עדיין Playbook מוסכם.","source_basis":"תמלול מלא שסופק (קובץ מקור 5, פריט 1). אין שאלות ותשובות בתמלול. תמלול אוטומטי עם שגיאות. הכותרת המלאה לפי הצגת המנחה.","lead":"כמו ב-DevOps, צריך צוות Enablement: לבנות את הדבר שבונה את הדבר, בארבע שכבות","chapters":[{"title":"המסגור: לבנות את הדבר שבונה את הדבר","body":["הוא פותח בכך שההרצאה התחילה ביום שישי כי 'מישהו גנב את הרעם' בהרצאה קודמת. הפיתוח משתנה: 'אנחנו לא בונים את הדבר, אנחנו בונים את הדבר שבונה את הדבר'. כולם ממציאים את הגלגל, כמו שבעבר כולם בנו deploy משלהם, או 'S3 משלהם'. זה לא בר-קיימא.","הוא משווה ל-developer enablement: זה לא קורה מעצמו, יש צוות שמטפח. הבשורה הטובה: כבר ידוע איך. כל מה שטוב לבני אדם בפרקטיקות הנדסה טוב גם לסוכנים ולהפך, אולי כי מודלים אומנו על ההתנהגות שלנו."],"points":[],"kind":"idea"},{"title":"שכבה 1: להכשיר את הסוכנים","body":["הוא מציין שה-'AI product engineer' הוא עוד תפקיד שמטשטש בין דרישות לביצוע. אתגר תפיסתי מרכזי: כשהסוכן טועה, אנשים קופצים ומתקנים את הקוד. צריך לתקן את המערכת שבונה את הקוד כדי שלא יצטרכו שוב. 'לתקן את המערכת ולא את הקוד', וזו עדיין לדבריו אחת הטעויות הנפוצות בתעשייה.","מה שנראה טוב: תכנון לפני ביצוע, בדיקות כדי לדעת אם הסוכן שבר פונקציונליות, ומפתחים שמתחילים לכתוב תיעוד (מפרטים והקשר) כי זה משפר. עם observability הסוכנים יכולים לשפר את עצמם. הכול מוכר, 'רק עם חשיבה חדשה'.","שימוש חוזר: ספק ספרייה משותפת בצוות במקום כל אחד עם CLAUDE.md משלו או העתקות מהרשת. יש כבר חמישה או שישה harnesses, ולדעתו רק מעטים ישרדו. צריך לתחזק מפרטים. בעיה נוספת: מערכות כמו טריאז' או מסד לקוחות לא הוגדרו היטב לבקרת גישה. לכן מגבילים את 'רדיוס הנזק' כמו במשתמשים. והמסר המרכזי למפתח: אחרי כל פעולה חשבו איך לא לחזור עליה, כמו באוטומציה של DevOps ('זה עובד אצלי' הופך ל'זה עובד עם הסוכן שלי')."],"points":[],"kind":"idea"},{"title":"שכבה 2: להכשיר את הצוות","body":["ראש צוות אחראי כעת גם לביצועי הסוכנים של חבריו, כי הכלים שבונים את התוכנה חלק מאחריותו. מטרות ברורות חשובות: 'אם רוצים שהוצאות הטוקנים יזנקו, תנו הנחיה מעורפלת ותריצו בלילה'.","דינמיקה חדשה: 'pair of context writing' (כתיבת הקשר בזוגות, כפי שהוא מנסח), הגדרת done שכוללת את ביצועי הסוכן, ומדד שהוא אוהב: כמה turns הסוכן צריך כדי לעשות נכון. חלק מהצוותים עושים ריטרו 'איך הסוכנים עבדו'. מדדי velocity לא מספיקים; יש גם rework. צריך הכשרה כי לא כולם כותבים טוב. מי שהיה 'רוקסטאר קוד' צריך להפוך ל'Agent Whisperer' ומסוכנים ספקנים אפשר לבקש 'תכתבו מה אתם עושים כדי שנשפר את הסוכנים'. הספרייה המשותפת בריפו מעלה שאלות בעלות."],"points":[],"kind":"idea"},{"title":"שכבה 3: פלטפורמה","body":["דפוס חוזר: צוות Agile, אחר כך DevOps, עכשיו צוות Enablement, שמתחיל באינקובציה ומתמזג לשכבה משותפת כדי שלא יכתבו boilerplate שוב ושוב. הם בונים 'עבור הצוות שבונה את הדבר שבונה את הדבר'. הוא מזכיר שביקש מספקי כלי קידוד אם הם לומדים ממה שקורה בפרודקשן ואין ביקוש לכך. שיתוף זיכרון ו'עמוד שדרה' משותף יגיעו מאוחר יותר.","פלטפורמה טובה: self-serve (בלי לעבור דרך העתקות של Skills), שיטות עבודה מומלצות, סריקות אבטחה, ו-observability מרכזי של סוכני קידוד בכל הארגון כדי לראות מה חסר בהקשר. Registry לגרסאות של skills, MCP, harnesses, סוכנים ו-pipelines (גילוי, שימוש חוזר, self-serve). Gateways (זהות, observability) ו-ownership: כמו מאגרים נטושים, צריך לדעת מי אחראי ומי מתקצב.","התנגדות 'אנחנו מיוחדים': בעבר אמרו זאת על DevOps; אחרי זמן כולם עשו. התאמות אישיות צריכות להיות מכוונות. אנשים מתעקשים על סוכן מהיר, אבל כשהוא רץ ברקע חשוב יותר שהתוצאה נכונה מאשר משוב מיידי."],"points":[],"kind":"idea"},{"title":"שכבה 4: ארגון (VP הנדסה)","body":["זהו תפקיד Enablement הרחב ביותר: 'לבנות את הארגון שבונה לצוותים'. נתנו כלים לכולם ו'עכשיו מה?' התחום המאתגר: לעקוב אחר הוצאות. הוא מציע: להבין איך כרטיסים זורמים אל מה שהסוכן יכול לגשת אליו; בעלות ברורה כי היא מניעה שיפור; איזון בין צוותים (צוות שמייצר יותר מכולם ולא ניתן לסקור); השקעה בהכשרה, pipeline ומדידה מעבר לרישיונות. ממשל: מי ניגש למה, סריקות אבטחה חובה, רשימת Skills מאושרים ותהליך להכנסת Skills חיצוניים, ו-KPI לאיכות סוכנים."],"points":[],"kind":"idea"},{"title":"איך מצדיקים השקעה","body":["הוא אומר שהעסק רוצה ROI עכשיו, ולכן צריך להפוך את הכאב לנראה, כמו באבטחה: בלי מדד לחולשות אי אפשר להצדיק, ו'x או 10x, נראה לי טוב' אינו מדד. הוא מזהיר מ'פרס ניצחונות מהירים'.","הוא אומר שאין playbook, וזה לא מספק. המודל המנטלי: חבית עם קרשים; הקרש הנמוך ביותר קובע, ולכן מתקדמים שכבה שכבה בממשל ובאוטומציה, בלי להאיץ אוטומציה בלי ממשל."],"points":[],"kind":"idea"},{"title":"למידה מתמשכת וכלי המחקר שלו","body":["כמו CI/CD, חשוב לאמץ טכנולוגיה חדשה מהר ולהצביר ידע בארגון. הוא מתאר סוכן שבנה שסורק פוסטים חברתיים ומזקק דפוסים כ'כלי מחקר' כי סקרים איטיים מדי. הוא מנסה להתעלם מדברי ספקים (אבל לפעמים הם צודקים) ולחפש כמה מקורות, ובודק אם הם מצטטים אותו מאמר. הוא מזמין לשתף סיפורים ולהתחבר ב-LinkedIn כדי לקבל את השקפים בתמורה למשוב."],"points":[],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["כמו ב-DevOps, צריך לבנות יכולת Enablement שתחסוך המצאת גלגל בכל צוות.","לתקן את המערכת ולא את הקוד, ולמדוד turns, rework והוצאות.","אין playbook; מתקדמים שכבה שכבה ומשקיעים בממשל לפני אוטומציה."],"kind":"idea"}],"diagram":{"kind":"layers","title":"ארבע שכבות Agent Enablement","nodes":[{"id":"o","label":"ארגון: ממשל, KPI, השקעה, איזון בין צוותים, בעלות"},{"id":"p","label":"פלטפורמה: self-serve, Registry, Gateway, observability מרכזי"},{"id":"t","label":"צוות: מדדי turns ו-rework, ריטרו סוכנים, הקשר משותף"},{"id":"a","label":"סוכן: תיקון המערכת, תכנון, בדיקות, הקשר משותף, הגבלת רדיוס נזק"}],"edges":[{"from":"a","to":"t","label":""},{"from":"t","to":"p","label":""},{"from":"p","to":"o","label":""}],"caption":"השכבות נבנות כך שכל אחת תומכת בבאה אחריה."},"terms":[{"term":"Agent enablement","definition":"עבודה של צוות שמאפשר ל-agents ולצוותים להשתמש בסוכנים בקנה מידה, דומה ל-developer enablement."},{"term":"Fix the system, not the code","definition":"במקום לתקן טעות של סוכן ידנית, לשפר את ההקשר או ה-harness כדי שלא תחזור."},{"term":"Turns","definition":"מספר הסבבים שהסוכן צריך כדי להגיע לתוצאה נכונה, כמדד ליעילות ה-harness."},{"term":"Agent whisperer","definition":"מפתח שהופך לספק הקשר מצוין לסוכנים."}],"gaps":["אין שאלות ותשובות בתמלול.","הדובר מציין שהחומר ניסיוני וש'אין playbook'; חלק מהיעדים (KPI) נשארו כלליים בכוונה.","השקפים אינם בתמלול.","הטענה שרוב האנשים עדיין 'קופצים ומתקנים' היא תצפית של הדובר.","ההשוואה ל-DevOps ושמות המונחים (Agent whisperer) הם של הדובר."],"source_refs":["https://www.youtube.com/watch?v=I9RWrW32QEw"]},{"number":27,"id":"PsEnuv3S5I0","url":"https://www.youtube.com/watch?v=PsEnuv3S5I0","type":"session","type_he":"סשן","duration":"31:51 דקות","title_he":"מחשב נפרד לכל סוכן: לקחים מפיתוח HelixML באמצעות עצמו","speaker_he":"לוק מרסדן","summary":"לוק מרסדן, מנכ\"ל HelixML (סוכנים פרטיים, ולפני כן מפעיל MLOps ובעבר מוביל מחזור חיי אשכולות בפרויקט Kubernetes), משתף החלטות תכנון ממערכת שמריצה סוכנים בשרת, בנוסף להדגמות. הוא מזהיר: 'ההרצאה כוללת דעות', והוא מסביר איך הגיע אליהן.","takeaways":["לא להריץ כמה סוכנים באותה תיקיית עבודה: stash או מחיקה פוגעים בכולם. לכל משימה סביבה מבודדת והגבלת מקביליות בלוח Kanban.","לפני מימוש, הסוכן קורא קוד ומרחיב בקשה למפרט. בני אדם מגיבים למסמך ומאשרים עיצוב לפני המימוש.","IDE ודפדפן מאפשרים לסוכן להריץ, לבדוק ולצלם שינוי. אדם בודק PR יחד עם המוצר הפעיל ולא רק דיפ.","סביבות נפרדות משתפות היסטוריית מפרטים בלי קבצים פעילים. בדוגמה Markdown נשמר בענף נפרד ומקושר למימוש.","הקמת סביבה חייבת להיות מהירה: Helix משתמש בשכפולי ZFS ובמטמון Docker מעודכן ל-main כדי לא לבנות מחדש עשרות דקות.","ניידות בין מודלים ופריסה עצמית עשויות להפחית עלות ותלות. בקרה על חיבורים והרשאות נשארת צורך פתוח ולא מוצגת כפתורה."],"category":"תשתיות וסביבת ריצה","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. טענת 80% מהעבודה למודל פתוח אינה Benchmark שאומת. דוגמת LinkedIn אינה המלצה ואינה מוכיחה עמידה בתנאי שירות.","source_basis":"תמלול מלא שסופק (קובץ מקור 5, פריט 2), כולל שלוש שאלות ותשובות. תמלול אוטומטי עם שגיאות (שמות כמו Zed, Wolf, GLM).","lead":"סוכן לכל מחשב ולא אדם לכל מחשב: Kanban, מפרט כמרכז, ופיתוח של Helix בעזרת Helix","chapters":[{"title":"התזה: כל עבודת מידע תהפוך לניהול סוכנים","body":["לדעתו כל עבודת מידע בסופו של דבר תהפוך לניהול סוכנים, ועבודת התוכנה היא רק התחלה. הוא מצטט את שלבי האימוץ שתיאר יוצר Gas Town (סטיב): מ-chat completion כמו Copilot, לסוכן CLI יחיד כמו Claude Code, ואז הרצת כמה במקביל. הבעיה שמתחילה: להריץ כמה סוכנים על אותה תיקיית עבודה.","הוא מספר: בבוקר יום שני הוא מיהר להכין מצגת ללקוח בפריז והריץ חמישה סוכנים במקביל. אחד עשה git stash לעבודה של האחרים, וביום שאחריו סוכן אחר הריץ rm -rf על ה-checkout. הוא עובד מ-2023 על הרצת LLM ו-RAG על תשתית פרטית, וסוף 2024 ('late last year') החליט 'לגרום לנחש לאכול את הזנב': להשתמש במוצר לבנות את עצמו."],"points":[],"kind":"idea"},{"title":"עמדה 1: מאגר מרכזי, וסוכן לכל מחשב","body":["החלטה גדולה: לתת לכל מפתח להריץ סוכן כרצונו בסביבה שלו ('פתית שלג'), או לבנות מאגר סוכנים בתשתית הארגון שאליו רבים ניגשים. הוא מצדד בגישה המרכזית. מרכזי אינו אומר למסור נתונים ל-OpenAI: אפשר על Kubernetes פרטי.","יתרונות: צוות גלובלי יכול להעביר עבודה כשהשמש שוקעת בטוקיו ועולה בלונדון, במיוחד כשלסוכן יש מחשב משלו למשימה. הוא מצטט לקוח (DevIcon, כפי שמתומלל) שציין ש'קידוד עם סוכנים אינו חדש; המעבר מהצד הלא בטוח לפר-מהנדס לצד הגלובלי והבטוח לפר-חברה' הוא המעניין. העמדה: 'תנו לכל סוכן מחשב משלו, לא לכל אדם': לא היית נותן לצוות מפתחים לחלוק מחשב אחד."],"points":[],"kind":"idea"},{"title":"עמדה 2: עדיין צריך IDE","body":["הוא אומר ש-Claude Code גרם לו להסתכל פחות בקוד ו'להיות טיפש יותר'. סוכנים יעשו משימות אוטונומיות ארוכות, אך כשצריך לעשות pair עם סוכן, צריך לראות קוד, ותצוגה חזותית שמלווה את הסוכן שימושית. הוא מוסיף שחשובה מהירות: הוא התעצבן על Cursor בהקלדה איטית, ומתלונן ש-Claude Code, שמומש ב-React, 'מיישם דפדפן בטרמינל' במקום תיבת טקסט פשוטה."],"points":[],"kind":"idea"},{"title":"עמדה 3: איך מארגנים סוכנים","body":["שתי אסכולות: להרחיב לפי מספר משימות, או לבנות 'ארגון' של סוכנים (CEO שמעסיק VP הנדסה שמעסיק מהנדסים עם שמות). הם התחילו מהראשונה כי קל יותר וחוקרים את השנייה. הממצא: כשנותנים תפקיד דק מדי לכל סוכן וערוצי תקשורת כמו 'Agent Slack', הם 'מידרדרים לפוליטיקה ארגונית' כי אומנו על נתוני אנושות, וזה שורף טוקנים.","מה שנראה לו מתאים: תפקידים גסי-גרגר (סוכני שיווק, מכירות, הנדסה, כי הם צריכים כלים וחיבורים שונים), ובתוכם הרחבה לפי משימה, כמו 'מאגר דבורים'."],"points":[],"kind":"idea"},{"title":"הדגמה: Kanban עם סוכן ומחשב לכל משימה","body":["Kanban מתאים להרחבה לפי משימה כי מגבילים מקביליות. בפרויקט דוגמה של אפליקציית משימות, לחיצה על play בבקלוג מפעילה שלושה מחשבים נפרדים לשלושה סוכנים (מצב כהה, תיקון באג, קטגוריות מותאמות). כדי לקבל חוויית background שמרגישה כמו foreground הם יישמו שולחנות עבודה מואצי GPU וקידוד וידאו חומרתי (טכנולוגיה מעולם משחקי הענן). הסוכן רץ בתוך IDE בשם Zed (הם יצרו fork שאפשר לשלוט בו מרחוק), והוא תומך ב-ACP ולכן מתחבר ל-Codex ול-Claude Code.","המפרט במרכז: הפרומפט האנושי קצר ('הוסף מצב כהה'); הסוכן בשלב תכנון קורא את הקוד וכותב מפרט מפורט יותר. לדברי לוק, כשמבקשים תוכנית לפני ביצוע, התוצאות 'הרבה יותר טובות' כי אפשר לתקן לפני שהסוכן יצא לדרך. אדם מגיב למפרט (כמו Google Docs), ואז מאשר ('Approve Design').","אחרי אישור, שלב המימוש: הסוכן מעלה PR, והאדם סוקר גם אותו וגם את האפליקציה הרצה במחשב של הסוכן, שהוא סביבת Docker-in-Docker (או על Kubernetes) כך שסוכנים לא פוגעים זה בזה ב-Chrome MCP. המפרטים הם קובצי Markdown בענף נפרד ב-git, כך שכל סוכן רואה את המפרטים של האחרים."],"points":[],"kind":"idea"},{"title":"נייד, מרובה משתמשים וסביבות מהירות","body":["מפתח מקיים אינטראקציה עם סוכן לכמה דקות בשעה ויכול ללכת לחדר כושר, ולכן הכול עובד גם בנייד וטאבלט (הוא מדגים עם הודעת LinkedIn על 'להריץ Zed ב-iPad בחדר כושר'). הם הוסיפו כמה סמנים כמו ב-Figma כדי שכמה אנשים יעשו pair על שולחן העבודה של סוכן אחד.","בעיה שעצרה אותם: בניית ה-stack מאפס ב-Docker לקחה 40 דקות. הפתרון: ZFS ליצירת clones, Docker-in-Docker (בפועל כשלוש רמות), והכנה של ספריית הנתונים עם סקריפט ההפעלה העדכני מול ה-commit האחרון ב-main, כדי שכל סוכן יתחיל בסביבה טרייה ושמורה במטמון. כך Helix בונה את Helix."],"points":[],"kind":"idea"},{"title":"איך נראה יום עבודה, עלויות והפרטיות","body":["רוב יום העבודה הטכני שלו הוא סקירת מפרטים: מוצא שתי שורות שבהן הסוכן טעה, מגיב, והשאר מכני. ה-PR כולל צילומי מסך ומקושר למפרט. כך הוא לעיתים סוקר PR רק לפי האם אוהב את השינוי.","עלויות: הטוקנים 'מתפוצצים' וזה כואב לחברה ממומנת עצמית. הוא טוען שמודלי משקלים פתוחים (כמו GLM 5.1) עושים כ-80% מהעבודה, ומציע להשקיע תקציב טוקנים של שלושה חודשים בחומרה (שמונה כרטיסי RTX 6000 Pro), ולהחליף בקלות בין סוכנים ומודלים, עם 'פריצה' אל Claude Opus 4.8 רק למשימות קשות. (במצגת נאמר גם 'פרטיות ו-Donald Trump' כנושא; התמלול לא מפרט מה נאמר על כך.)"],"points":[],"kind":"idea"},{"title":"עסק משפר את עצמו, ושימוש מחוץ לתוכנה","body":["חזון: בבסיס בסיס קוד מתקן עצמו (issues בלוח Kanban); מעליו סוכני מוצר ותמיכה שמשפרים לפי משוב; ומעליו סוכני מכירות, שיווק, כספים ומשפט ו'רמת מייסד', הכול עם אדם בלולאה.","דוגמה: הם התחברו עם הסוכן ל-LinkedIn ('הסוכן כמו חליפה מכנית') ובנה רשימה של 200 אנשים לפנייה בעת ביקור באזור המפרץ. הסוכן ביקש 'תעשה אימות דו-שלבי בבקשה', וממנה התקבלו פגישות. סיכום: מרכזי מול מקומי, IDE, הרחבה לפי משימות, spec-driven, נייד ומרובה משתמשים, סביבות פיתוח מהירות, ועלויות טוקנים."],"points":[],"kind":"idea"},{"title":"מה לגבי אבטחה כשסוכן יכול להתחבר ל-LinkedIn ולעשות כל דבר?","body":"הוא אומר שהם כבר טובים יותר מהרצת סוכן פתוח על Mac mini: סוכן מחובר רק לאתר אחד. אפשר להגדיר לכל פרויקט איזה שרתי MCP חשופים. הוא מכיר בצורך בכלי נעילת הרשאות ובפאנל ממשל, ומעדיף שותפות עם גורמים אחרים.","kind":"qa"},{"title":"איך מריצים את מכונות ה-GUI?","body":"מריצים mutter (קומפוזיטור של GNOME) בתוך קונטיינר ומזרימים. פרויקט Wolf לגיימינג ב-C++ היה לא יציב ופעל בתהליך אחד, ולכן לקחו ממנו רק את רכיב ה-Rust ל-NVIDIA CUDA. הקוד ב-GitHub.","kind":"qa"},{"title":"למה צריך IDE ואיך הוא נראה?","body":"הם הטמיעו Zed (Rust, מהיר, זיכרון קטן שחשוב כשמריצים מאות). הוא אוהב לראות את הסוכן קופץ בין קבצים, ו'סופג' ידע על הקוד, בניגוד ל'קופסה שחורה' של Claude Code. הוא צריך IDE בפנים וגם 'מטא-IDE' של מישור בקרה לכל הסוכנים.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["הרצת סוכנים על מחשב משלהם במרכז הארגון נותנת בידוד, שיתוף ומקביליות.","מפרט שנסקר על ידי אדם הוא נקודת הבקרה העיקרית.","עלויות טוקנים ופרטיות מצדיקות להסתכל על מודלים מקומיים."],"kind":"idea"}],"diagram":{"kind":"flow","title":"מחזור משימה ב-Helix כפי שהוצג","nodes":[{"id":"b","label":"Kanban: משימה בבקלוג"},{"id":"d","label":"מחשב/שולחן עבודה לכל סוכן (GPU, Docker)"},{"id":"p","label":"שלב תכנון: מפרט Markdown בענף נפרד"},{"id":"h","label":"אדם: הערות ו-Approve Design"},{"id":"i","label":"מימוש + PR עם צילומי מסך"},{"id":"q","label":"אדם: סקירת PR והאפליקציה הרצה"}],"edges":[{"from":"b","to":"d","label":"play"},{"from":"d","to":"p","label":""},{"from":"p","to":"h","label":""},{"from":"h","to":"i","label":""},{"from":"i","to":"q","label":""}],"caption":"לפי תיאור הדובר והדגמה; חלק מהשלבים הואצו בסרטון."},"terms":[{"term":"Agent desktop","definition":"שולחן עבודה גרפי ממדוד לכל סוכן, עם דפדפן ו-IDE, לצורך בדיקות והדגמה."},{"term":"Scale by task","definition":"הרחבת מספר הסוכנים לפי מספר המשימות, בניגוד לארגון סוכנים לפי תפקידים."},{"term":"ACP","definition":"פרוטוקול (כפי שנאמר) שמחבר את Zed לכלי סוכנים כמו Codex ו-Claude Code."},{"term":"Spec review","definition":"סקירת מפרט שנכתב על ידי הסוכן, לפני שמתחילים לממש."}],"gaps":["התמלול לא מסביר את הנושא 'Donald Trump' שהופיע בכותרת הקטע על עלויות ופרטיות.","תאריך 'late last year' אינו מדויק בתמלול.","הסרטונים והשקפים אינם זמינים, ורק מה שנאמר.","הטענות על 80% מהעבודה עם מודלים פתוחים, 'הפכתי לטיפש יותר', ו'פתיות Claude Code ב-React' הן דעות הדובר.","דוגמת DevIcon ו-LinkedIn הן עדויות של הדובר."],"source_refs":["https://www.youtube.com/watch?v=PsEnuv3S5I0"]},{"number":28,"id":"tJUAef_dBtU","url":"https://www.youtube.com/watch?v=tJUAef_dBtU","type":"session","type_he":"סשן","duration":"31:03 דקות","title_he":"לבנות צוותי מוצר בעידן AI: מה ללמוד מחדש בכל רבעון","speaker_he":"כריסטופר בייטי","summary":"כריסטופר בייטי, CTO בחברת ייעוץ להנדסת פלטפורמות ו-Continuous Delivery, מתאר איך התארגנו מחדש כדי לבנות מוצרים שמנהלים מידע רגיש וסביבות פרודקשן, כשכמעט כל הקוד נכתב על ידי AI. הוא מציג הדרכה ('לא להאציל חשיבה מערכתית'), ארבע החלטות תהליך, ושינוי מבנה צוותים.","takeaways":["לא להעביר חשיבה מערכתית לסוכן. בחיבור מערכת לקוח לשירות מרובה דיירים מכריעים במפורש באימות, הרשאות, חשיפת API ותנועת נתונים.","ADR קצר עם תרשימים נבדק ב-PR נפרד לפני מימוש. לאחר אישור, הסוכן בודק התאמה גם בשינויים עתידיים.","להבחין בין Harness, שירות שמארח מודל והמודל עצמו. תלות בספק היא בחירה מודעת; מעבר מהיר חשוב בזמן תקלה.","לזהות צוואר בקבוק מרעיון עד אימוץ, לא רק עד Merge. מהנדס אחראי לבנייה, תפעול ולמאמץ אימוץ לפני פיצ׳ר חדש.","לעבוד במקביל אבל על משימה מורכבת אחת בכל פעם. בזמן המימוש מקדמים עבודה קלה יותר בלי לצבור החלטות ארכיטקטורה כבדות.","צוותים של שניים עד ארבעה מקבלים יעד שימוש לקוח עם תיאום ארכיטקטוני. צימוד רופף, בדיקות מהירות וצמצום רדיוס נזק מגינים על קצב כשהמוצר גדל."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. יש מסקנות ותודה, אך התמלול נעצר בתחילת תגובת המנחה. אין שאלות ואין בסיס לאשר כיסוי סוף הווידאו. אחוז קוד AI מוגדר מדד יוהרה אם אין הבנה ואחריות. דוגמת סוגי בדיקות שהובטחה לא הוצגה בגלל זמן; אין לשחזר אותה.","source_basis":"תמלול מלא שסופק (קובץ מקור 5, פריט 3). אין שאלות ותשובות; ההרצאה נסגרת ברשימת מסקנות. הכותרת בקובץ קטועה ('What We Had to Relear...'), והכותרת כאן מושלמת מהכותרת המקורית שהוצגה למנחה כ'What we had to relearn every quarter'.","lead":"מערכות שחשובות לא נבנות בלי הבנה אנושית: ADR, אחריות על אימוץ, צוותים קטנים ומשימה אחת מורכבת בכל פעם","chapters":[{"title":"הרקע: מחברת ייעוץ למוצרים","body":["החברה הייתה חברת ייעוץ בתחום הנדסת פלטפורמות ו-CD ללקוחות גדולים (מדיה, פיננסים, בריאות): ייעוץ ומהנדסים. כדי לשמור על יתרון בידע בנו מערכות פנימיות: ויקי וחוברות והכשרה, גיליונות להערכת בגרות, ומפות דרכים עם יישומי ייחוס.","היום, לדבריו בזכות AI: הכשרה פנימית אינטראקטיבית שמקצה סביבה אמיתית (מאגר GitHub, namespace ב-Kubernetes, חשבון ענן) ובודקת אוטומטית שהמתאמן עשה (למשל פרס artifact בלתי משתנה); כלי מעקב אחר בגרות (אבטחה, ארכיטקטורה, בדיקות) שהפך ל-SaaS ללקוחות; ומפות הדרכים נהפכו לפלטפורמת פיתוח מדף לחברות קטנות. הוא אומר שהחברה לא הייתה יכולה להרשות לעצמה צוות מוצר של עשרה אנשים לפני שנתיים. החברה משתמשת במוצר שלה בעצמה."],"points":[],"kind":"idea"},{"title":"מה בסיכון: מערכות שחשוב שלא ייכשלו","body":["שני סוגי מערכות: אחת שמחזיקה מידע רגיש ודליפה תסיים קשר עם לקוח, ושנייה שמנהלת סביבת פרודקשן של לקוחות. הוא אומר שהוא לא מדבר על פרויקטי צד או עסקים של אדם אחד, אלא על מערכות עם פרטי אשראי או מידע בריאותי. 'אנחנו מתקרבים לעולם שבו תוכנה שאף אדם לא ראה מגיעה לפרודקשן, וזה כבר לא היפותטי'.","הוא מודה שבשנה האחרונה AI מצוין בכתיבת קוד (בתחילה 50/50 אם יתקמפל, כעת עובד ברוב המקרים), אך שואל: האם כתיבת קוד היא החלק הקשה ביותר? ובסקר ידיים בקהל: מי כותב פחות מ-10% מהקוד עם AI (אחד או שניים), מי מעל 90% (רבים). אצלם 90 עד 100%, אבל זה 'מדד הבל', כי השאלה היא כמה קוד נכתב בלי חשיבה ביקורתית אנושית. 'AI הוא מגבר: מה שעשינו טוב נעשה מהר, ומה שעשינו רע מוגבר גם כן'. על קוד שלא עובר לפרודקשן בלי שבן אדם מבין אותו, גם כאן שאל את הקהל: חלק קטן עד מחצית מצהירים שאף קוד לא כך; כמה ידיים בקצה 100%."],"points":[],"kind":"idea"},{"title":"טיפ 1: לא להאציל חשיבה מערכתית","body":["הוא מתאר 'קופסה שחורה' של הפקת המוצר: מכלול נכס דיגיטלי (קוד, בדיקות, ניטור, תיעוד) שהמפיק שלו הפך ל-agent. 'אנחנו מרגישים בטוחים אם מבינים את בדיקות הקבלה', אבל זה הופך בהדרגה למצב שבו אף אחד לא מבין.","דוגמת ארכיטקטורה: שירות מנוהל ל-multi-tenant עם צד לקוח (agent שנפרס אצל הלקוח כי הנתונים לא עוזבים את הרשת) ואימות. הוא יכול לתאר פיצ'ר שמשלב בין השניים והסוכן יבנה אותו, אך ה-PR יכלול אלפי שינויים. מה צריך לבדוק? איך הצד של הלקוח מתחבר ומתאמת, אילו חלקים חשופים לאינטרנט, האם API משותף לבני אדם ולמערכות סוכנים, איזה מידע עובר, ואיך פורסים (שירות מנוהל בפריסה רציפה, וצד הלקוח אולי פעם בשבוע).","התהליך החדש: כל החלטה ברמת מערכת מגיעה כ-PR נפרד של Architectural Decision Record (ADR). בעבר הסוכנים אהבו לכתוב ADR ויצרו מסמכים ארוכים שאף אדם לא הבין. כעת מתחילים מה-ADR, אדם משקיע בסקירה, עם דיאגרמות חזותיות, ורק אז הסוכנים מממשים וסוכנים בודקים כל PR בהמשך מול ה-ADR (כי בני אדם לא זוכרים את כולם)."],"points":[],"kind":"idea"},{"title":"טיפ 2: ההפקה מורכבת משלושה רכיבים","body":["הוא מפרק את ה'מפיק' לשלושה: ממשק (harness כמו Claude Code, Codex או workflow על issues), אירוח המודל (ה-API או מארח אחר), והמודל עצמו. כולם קופסאות שחורות. אפשר להתנתק מעט: harness פתוח כדי להחליף ספק בפקודה אחת כשספק מושבת (עם תוצאות שונות), אירוח עצמי או מודל משקלים פתוחים.","הוא טוען שחשוב יותר להבין את המוצר, כי זה קניינכם. אם בונים אינטראקציות AI בתוך המוצר, יש קופסה שחורה בתוך קופסה שחורה. נעילה לספק מקובלת אך צריכה להיות בחירה מודעת עם הבנת השלכות של נפילה בזמן קריטי."],"points":[],"kind":"idea"},{"title":"טיפ 3: זרימה מרעיון לאימוץ","body":["כל שינוי במוצר הוא ניסוי, ואין טעם בניסוי בלי לבדוק תוצאה. ההאצה שונה בכל שלב: בנייה זינקה בסדר גודל. ניהול מוצר מקבל האצה עם AI בניתוח משוב ומחקר, אך החלטות מה לבנות ובאיזה סדר אינן מאוצלות. לפעמים אפילו קשה יותר כי מספקים יותר מדי פיצ'רים ללקוחות והאימוץ נהיה קשה.","הכלל החדש: מהנדסים אחראים ישירות לאימוץ הפיצ'רים שבנו, ואסור להם לבנות את הפיצ'ר הבא עד שעשו כל מה שאפשר לאמצו. 'You build it, you run it' הפך ל'בנית, מפעיל, ומניע אימוץ'. אחרת נשארים עם פיצ'רים לא בשימוש כי זה כיף."],"points":[],"kind":"idea"},{"title":"תפקיד המהנדס: תכנון, ביצוע, חידוד","body":["שלושה שלבים: תכנון טכני (ארכיטקטורה, אסטרטגיית בדיקות, אינטגרציות), ביצוע (קוד, 'נעים כמו קפה'), וחידוד לפי משוב משתמשים. הוא ממליץ על ספריית Superpowers (brainstorming לתכנון, אך 'אל תאצילו, זה ישאל הרבה שאלות ויגרום לכם להרגיש מיודעים' והבחירה שלכם) וכתיבה וביצוע תוכניות.","בעבר תכנון קצר, ארוך קידוד ('טיפולי'), ואז אימות ופריסה. היום תכנון הוא החלק הכבד. אנשים מרגישים גיבור על, ואז ממורמרים כי AI איטי (30 דקות לשינוי של 4,000 שורות), ולכן מתחילים משימה נוספת, ועוד אחת, ונהיים עייפים. כלל: עבודה במקביל כן, אבל רק משימה מורכבת אחת בכל פעם. אחרת הראשונה מצוינת, השנייה פחות והשלישית 'זבל', כי המוח כבר נוצל."],"points":[],"kind":"idea"},{"title":"צוותים: קטנים, עם משימה ואחריות לאימוץ","body":["הוא רוצה צוות אנשים שמפעיל ומתחזק ולא גיבור יחיד ולא מערכת AI ללא אחריות. הוא מתלוצץ על 'צוות שתי פיצות' (6 עד 8). בלי חשיבה, כולם מכורים להנדסה ומייצרים 48 PRs, וצוואר הבקבוק הוא סקירות. הוא מזכיר שנות עשרים של פרקטיקות לבניית הבנה משותפת (XP, pairing).","לכן צוותים של 6 עד 8 פוצלו לצוותי משנה של שניים עד ארבעה, כל אחד עם משימה: אימוץ אצל לקוחות מסוימים. אי אפשר להתחיל פיצ'ר הבא בלי לדבר עם הלקוח על הקודם. צוות המשנה סוקר, מתקן באגים ואוסף משוב. ('שלוש פיצות'.) הסיכון: הצוותים הולכים לכיוונים שונים, ולכן צריך בעלות מוצר ביניהם, סקירת החלטות ארכיטקטוניות על ידי הנכונים, ולפחות אדם אחד או שניים שחוצים זרמים."],"points":[],"kind":"idea"},{"title":"האם AI שינה פרקטיקות הנדסה טובות?","body":["הוא מציג גרף שהוא 'המציא ללא נתונים': מהירות גבוהה בהתחלה, אחר כך האטה, תיקון, האטה, ובסוף מתחת למה שהתחלנו. הסיבות: חוב טכני (מחזורי בדיקות ארוכים, תלויות, קושי בשינוי) והצלחה (יותר לקוחות, פריסות, נתונים).","פרקטיקות שחשובות יותר: ארכיטקטורה (מערכות 'מצומדות בצורה רופפת' ומחזורי משוב קצרים; 15 דקות מקסימום להרצת חבילת בדיקות מלאה) ורדיוס פגיעה (אם רכיב אחד נופל, רוב הפונקציונליות עובדת)."],"points":[],"kind":"idea"},{"title":"מסקנות אחרונות","body":["הוא מתכוון להפוך את ההרצאה למאמרים באתר החברה ומציע לשלוח אותם."],"points":["הגדירו עקרונות לשימוש ב-AI: מה אנשים מבינים ומה סוכנים, ואיזו נעילה לספק מקובלת.","זהו צוואר בקבוק אמיתי מהרעיון ועד אימוץ, ואל תיפלו למדדי הבל כמו טוקנים, commits או PRs. 'פיצ'רים בפרודקשן' כבר לא מספיק; הם צריכים להיות בשימוש.","הגדירו 'טוב' באופן קונקרטי והחזיקו את ה-AI אחראי לכך."],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["לא להאציל חשיבה מערכתית: ADR נסקר על ידי אדם.","האימוץ הוא האחריות של המהנדסים, ולא רק בנייה.","צוותים קטנים עם משימה ומשימה מורכבת אחת בכל פעם."],"kind":"idea"}],"diagram":{"kind":"flow","title":"זרימה מרעיון לאימוץ אצל Batey","nodes":[{"id":"i","label":"רעיון וניהול מוצר (אדם מחליט מה ובאיזה סדר)"},{"id":"a","label":"ADR: החלטה מערכתית כ-PR נפרד שנסקר בעומק"},{"id":"b","label":"תכנון - ביצוע (סוכנים) - חידוד"},{"id":"v","label":"סקירה מול ה-ADR והבדיקות"},{"id":"d","label":"פריסה"},{"id":"u","label":"אימוץ: המהנדסים אחראים לפני הפיצ'ר הבא"}],"edges":[{"from":"i","to":"a","label":""},{"from":"a","to":"b","label":""},{"from":"b","to":"v","label":""},{"from":"v","to":"d","label":""},{"from":"d","to":"u","label":""},{"from":"u","to":"i","label":"משוב"}],"caption":"הסדר נבנה מדברי הדובר; הוא תיאר זאת בכמה שקפים."},"terms":[{"term":"ADR","definition":"Architectural Decision Record: מסמך החלטה ארכיטקטונית שנשמר בקוד, כאן נסקר על ידי אדם בלי האצלה."},{"term":"AI as amplifier","definition":"AI מגביר גם מה שעובד טוב וגם מה שעובד רע בארגון."},{"term":"Blast radius","definition":"היקף הנזק כשרכיב נכשל."},{"term":"Vanity metric","definition":"מדד כמו אחוז קוד שנכתב על ידי AI או טוקנים, שאינו מספר אם המוצר מועיל."}],"gaps":["אין שאלות ותשובות בתמלול.","הכותרת בקובץ המקור קטועה; הכותרת המלאה ('What We Had to Relearn Every Quarter') נלקחה מהצגת המנחה, לא מהכותרת הקטועה.","הדובר הזכיר דוגמת בדיקות שלא הספיק להציג, ולכן אין פירוט שלה.","אחוזי הקוד שנכתב על ידי AI (90 עד 100%) ותיאור הצלחת המוצר הם דברי הדובר.","הגרף על 'מהירות לאורך זמן' הומצא לדבריו ללא נתונים."],"source_refs":["https://www.youtube.com/watch?v=tJUAef_dBtU"]},{"number":29,"id":"Ex1Zu0qel8M","url":"https://www.youtube.com/watch?v=Ex1Zu0qel8M","type":"session","type_he":"סשן","duration":"32:18 דקות","title_he":"להטמיע סוכן קידוד בתוך המוצר: אבני הבניין של Pi","speaker_he":"מתיאס ליבקן","summary":"מתיאס לובקן, מהנדס AI ומייסד סוכנות קטנה בבריטניה ובגרמניה, מראה איך הקסם של OpenClaw מבוסס על סוכן הקוד Pi (של מריו צכנר) וכיצד ניתן לשלב אותו במערכת עסקית. הדוגמה: מערכת הצעות מחיר ללקוח בתחום חלקי חילוף, שבה כל לקוח הוא סוכן וכל תיק הוא סשן. הוא מסיים ברעיון של תוכנה גמישה (malleable software).","takeaways":["לתכנן כלים בעלי כוונה ברורה והיקף מוגבל. לא לתת כלי מסוכן ואז לסמוך על משפט שאוסר להשתמש בו.","הסוכן יוצר טיוטות אך אינו מקבל כלי שליחת מייל. זה גבול מבני, לא בקשת אישור בפרומפט.","Extensions פועלים לפני קריאה ואחרי תוצאה. למשל, בדיקת דומיין נמען בטיוטה או הזרקת מידע דינמי לשלב הנוכחי.","להרכיב בנפרד הקשר עסקי, משימתי ולקוח. אותה תשתית משרתת זרימה, צ׳אט מתקדם או ממשק עשיר בתוך צ׳אט.","סשן הוא יומן אירועים במבנה עץ המאפשר חקירה ושחזור. הפקת Skills מהיסטוריה והערכות עליהן היא כיוון שהדובר בוחן.","תוכנה שמשתנה לפי רצון המשתמש היא חזון ניסויי. התאמת Extensions חייבת להישאר בגבולות כלים והרשאות."],"category":"כלים ופרוטוקולים","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. התיאור מציג OpenClaw כמבוסס Pi, אבל הדובר מתקן שהוסר ממנו כשבועיים קודם. אין להציג את התיאור כמצב נוכחי. זה אבטיפוס. צ׳אט למשתמש מתקדם וניווט העץ טרם נחקרו לעומק.","source_basis":"תמלול מלא שסופק (קובץ מקור 5, פריט 4), כולל שתי שאלות וגם תשובות. האיות 'Lübken' בפתיחה והכותרת בקובץ תואמים; חלק משמות המוצרים בתמלול ASR.","lead":"איך לשכון סוכן קוד מינימלי בתוך מוצר רגיל: כלים מדויקים, hooks של guardrails, וסשנים כיומן שאפשר להפוך לכישורים","chapters":[{"title":"הקסם של OpenClaw ומה שמתחת לקפוט","body":["הדובר מספר שבינואר, בעקבות הבהלה סביב OpenClaw, ארגן אירוע בקלן וגילה ב'חפירה בקוד' את Pi. בקהל כמעט כולם מכירים אותו עכשיו, אף שלפני חודשיים כמעט אף אחד לא. השאלה שלו: איך מתכננים מערכות שמספקות אותו קסם?","בדוגמה שבה אדם שלח הודעה קולית ל-OpenClaw, הסוכן קיבל קובץ שאינו טקסט, השתמש בפקודות יוניקס רגילות כדי לזהות אותו כקובץ wave, ניסה לפענח בכלי whisper (ללא הצלחה), מצא בהוראות שאפשר לשלוח אל OpenAI API, חיפש מפתח, וחזר על כך בלולאה עד שהמטרה הושלמה. מבחוץ זה נראה קסם; מבפנים זו לולאה של כלים.","ההגדרה שלו: סוכן הוא כלים בלולאה, וסוכן קוד הוא סוכן שיש לו בנוסף bash, כלומר כל כלי הלינוקס וסביבת הרצה."],"points":[],"kind":"idea"},{"title":"Pi: מינימליזם כתכונה","body":["Pi נבנה על ידי מריו צכנר מווינה. את Pi מגדירים בעיקר במה שאין בו: אין שרתי MCP, אין תת-סוכנים, אין חלונות אישור הרשאות, אין plan mode, אין רשימת משימות מובנית ואין bash ברקע. אבל אפשר לבקש מ-Pi ליצור זאת.","הדוגמה: מבקשים 'צור הרחבה שמבקשת אישור כשאני דוחף את main לרימוט'. Pi יוצר קבצי TypeScript ו-markdown (בשם כמו pre-push guard), ובדחיפה מופיע חלון אישור. הסוכן הותאם בדיוק לדרך העבודה, וזה הוביל את הדובר לשאול איך זה ישנה תוכנה."],"points":[],"kind":"idea"},{"title":"האפליקציה לדוגמה: הצעות מחיר ללקוח","body":["אב טיפוס ללקוח שמערכת הצעות המחיר שלו איטית מדי. בתהליך שירות אחרי מכירה, דואר נכנס מבקש חלקים ויש הרבה עיבוד ידני. לדבריו אין צורך ב-AI כדי לפתור זאת, אבל AI מפשט ואולי יאפשר יותר מקרי שימוש.","הארכיטקטורה בהשראת OpenClaw: gateway שמנתב, סוכן אחד לכל לקוח (עם פרומפטים משלו כמו SOUL.md וכו'), וסשן אחד לכל תיק. מדובר בדשבורד עם KPIs ופעילות ותיבת דואר משוכפלת (בעתיד על Outlook). כשמייל מגיע, המערכת מחפשת תיק או יוצרת אותו, מציגה את פרטי הלקוח ושלבי התיק.","בתצוגת העומק רואים את הפרומפט של המערכת ואת הכלים: אחד לקריאת מצב התיק מה-CRM, אחד לחיפוש חלקים ב-ERP (שניהם APIs) ובסוף טיוטת מייל. המערכת לא שולחת מיילים אלא רק מכינה טיוטות, כדי שהמשתמש יסקור ויערוך. הטיעון: סקירה מהירה יותר מכתיבה. הוא מעיר ש-Pi הוסר מ-OpenClaw לפני כשבועיים, ולכן צריך לשנות את כותרת ההרצאה."],"points":[],"kind":"idea"},{"title":"פרימיטיב 1: הגדרת הסוכן","body":["משתמשים ב-SDK של סוכן הקוד (אותו דבר שמפתח מריץ בשולחן העבודה): מגדירים מודל, כלים, ניהול סשנים ומשאבים לטעינה. במקום AGENTS.md יחיד יש קבצים לשימוש חוזר: תיאור עסקי כללי, הנחיות למשימה (כיצד לשאול את הלקוח) והקשר ספציפי ללקוח (הנחות וכו'). בכישורים (skills) כמעט לא משתמשים בינתיים, אבל מבקרים כיצד הם נטענים."],"points":[],"kind":"idea"},{"title":"פרימיטיב 2: כלים","body":["ה-LLM מחליט מתי לקרוא לכלים, ולכן עיקר העיצוב הוא בהגדרת הכלים. שלושה כלים: מצב ה-CRM, חיפוש ב-ERP ומייל. הכלל שלהם: 'אל תגרמו לסוכן לנחש': הגדרה מדויקת, כלי שחושף כוונה, מוגבל למשימה. אפשר להחליף כלים תוך כדי עבודה.","הסוכן בעצמו חושף איך להשתמש בכלים (למשל מריץ עם help או קורא הודעות שגיאה). ואל תיתנו כלים שהסוכן לא צריך להשתמש בהם; אנשים כותבים 'אל תשתמש בכלי הזה' בהוראות, אך מוסרים אותו בכל זאת ואז מופתעים שמחק את מסד הנתונים. ('Data Box' הוא כלי של החברה שמסייע בכך.)"],"points":[],"kind":"idea"},{"title":"הרחבות ו-hooks של מחזור חיים","body":["ב-Pi אפשר לכתוב הרחבות על אירועים: מחזור חיים של סוכן וסשן, וביצוע כלים. אי אפשר לשלוט שה-LLM יקרא לכלי, אבל אפשר להתערב לפני קריאה או אחרי תוצאה, לסנן או לעבד.","דוגמה מהמערכת: בטיוטת מייל נבדק בדיקת שפיות שהכתובת בדומיין של הלקוח. עד כה זה תמיד עבר, אבל ככה לא סומכים רק על הוראות. אפשר להוסיף כל לוגיקה עסקית. הזרימה נשארת פתוחה אך חלק מה-guardrails מובטחים. hooks משמשים גם להזרקת מידע בהקשר (context engineering) כשאי אפשר לטעון הכול מראש."],"points":[],"kind":"idea"},{"title":"פרימיטיב 3: סשנים","body":["סשן ב-Pi הוא יומן אירועים בצורת עץ (JSONL) עם הודעות, שינויי מודל והודעות מותאמות (שנשלחות ל-LLM או לא). קל לחזור אחורה ולנסות נתיב אחר תוך שמירה על כל ההקשר.","במערכת: קונטיינר סוכן ללקוח וסשן לתיק. יומן הסשן מאפשר לסוכנים אחרים לעבוד על אותו מידע, לשחזר צעדים אם אדם שינה משהו, ולחלץ דפוסים. הם בוחנים לעבור על יומני סשן וליצור מהם skill (עם evals). לגבי מבנה העץ, הם עוד לא חקרו אותו הרבה."],"points":[],"kind":"idea"},{"title":"תבניות לאפליקציות","body":["תבנית 1: workflow חכם, שבו נותנים בעיה, כלים והרחבות והסוכן מסתגל. תבנית 2: צ'אט למשתמש מתקדם שמשתמש באותו סוכן קוד משובץ (כמו Cowork בתוך המערכת) על סשנים קיימים או חדשים; כרגע אין פרסונה אמיתית שמשתמשת. תבנית 3: משהו בין השניים, ממשק עשיר (בהשראת MCP UI/MCP apps): במקום JSON גולמי של חיפוש חלקים, ממשק שאפשר לשנות בו כמות."],"points":[],"kind":"idea"},{"title":"תוכנה גמישה (malleable software)","body":["הוא מפנה למאמר של Ink & Switch על מערכות תוכנה כמערכת אקולוגית שבה כל אחד מתאים כלים לצרכיו בחיכוך מינימלי, בדימוי של מסחרי 'מטבח' עם מכשיר חיתוך מסובך מול סכין רגילה שאפשר להתאים. הרעיונות ישנים אבל AI מאפשר אותם.","השאלה שלו: מה אם התוכנה תוכל לשנות את עצמה כמו Pi? הרחבה היא רק TypeScript, אז משתמש מתקדם יוכל לומר 'ודא שלא נשלחים מיילים שאינם בדומיין הלקוח'."],"points":[],"kind":"idea"},{"title":"שאלות מהקהל","body":["על אבטחה כשמשתמשים מתאימים תוכנה: רמת החופש צריכה להישאר בגבולות. כלי הטיוטה בנוי כך שהמערכת לא יכולה לשלוח, ולכן המשתמש תמיד שולט. הרחבות מוסיפות שכבת guardrails נוספת, ומשתמשים מתקדמים יכולים לבחור כמה בדיקות להוסיף. על ההבדל בין Pi לשרת MCP של Gmail: לבנות כלים זה חשוב, אבל השאלה מה עושים בהם; ההצעה היא לשבץ את כלי ה-MCP בתוך תוכנה גדולה יותר (למשל כלי אוטומציה למייל) באמצעות harness של סוכן קוד כמו Pi."],"points":[],"kind":"idea"},{"title":"איך מנהלים אבטחה כשמשתמשים מתקדמים יכולים להתאים את התוכנה?","body":"שומרים את החופש בגבולות: הכלים מוגדרים כך שהסוכן רק מכין טיוטות ולא שולח, וההרחבות מוסיפות guardrails.","kind":"qa"},{"title":"מה ההבדל בין Pi לשרת MCP של Gmail שבניתי?","body":"הכלים חשובים, אבל כדאי לשלב אותם בתוכנה גדולה יותר דרך harness של סוכן קוד.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["כלים מדויקים וחושפי כוונה, hooks לבדיקות, ויומן סשן הם שלוש אבני הבניין.","אל תיתנו לסוכן כלי שלא אמור להשתמש בו.","הדובר אומר שזה אב טיפוס מוקדם."],"kind":"idea"}],"diagram":{"kind":"layered","title":"הארכיטקטורה: סוכן לכל לקוח, סשן לכל תיק","nodes":[{"id":"g","label":"Gateway: ניתוב דואר נכנס"},{"id":"a","label":"סוכן לכל לקוח (AGENTS.md עסקי, משימה, לקוח)"},{"id":"s","label":"סשן לכל תיק (יומן עץ JSONL)"},{"id":"t","label":"כלים: מצב CRM, חיפוש ERP, טיוטת מייל"},{"id":"h","label":"hooks: בדיקת דומיין לפני/אחרי קריאה"},{"id":"o","label":"טיוטה לסקירה אנושית"}],"edges":[{"from":"g","to":"a","label":""},{"from":"a","to":"s","label":""},{"from":"s","to":"t","label":""},{"from":"t","to":"h","label":""},{"from":"h","to":"o","label":""}],"caption":"סידור הרכיבים נבנה מתיאור הדובר ואינו שקף מקורי."},"terms":[{"term":"סוכן קוד","definition":"סוכן עם כלים בלולאה ובנוסף bash וסביבת הרצה."},{"term":"Pi","definition":"סוכן קוד מינימלי של מריו צכנר, ניתן להרחבה על ידי קוד שהסוכן עצמו יכול לכתוב."},{"term":"Lifecycle hook","definition":"נקודת התערבות לפני קריאה לכלי או אחרי תוצאה, להצבת guardrails."},{"term":"Malleable software","definition":"תוכנה שמשתמשים יכולים להתאים בעצמם בחיכוך נמוך."}],"gaps":["שמות כמו Ink & Switch, Data Box ו-Cowork מתומללים אוטומטית ואינם מאומתים.","לא הוצגו נתוני ביצועים של המערכת.","ההצהרה ש-Pi הוסר מ-OpenClaw לפני כשבועיים היא דברי הדובר."],"source_refs":["https://www.youtube.com/watch?v=Ex1Zu0qel8M"]},{"number":30,"id":"M6Nhl4zR0uk","url":"https://www.youtube.com/watch?v=M6Nhl4zR0uk","type":"session","type_he":"סשן","duration":"27:09 דקות","title_he":"מוח מוצר: איך מנהלי מוצר נעשים מתזמרי סוכנים","speaker_he":"אמה בורוז","summary":"אמה בארוז, מייסדת Rezonant (סביבת עבודה למוצר), מציגה מערכת 'מוח מוצר' שקולטת מקורות (פגישות, GitHub, מייל, Linear), מסנתזת אותם לוויקי בריפו, ומפעילה workflows אוטונומיים עם בקרה אנושית. היא מציגה הדגמה של שתי כרטיסיות ושאלות ארוכות מהקהל.","takeaways":["קליטה מעדכנת ידע מכרטיסים, שיחות לקוח, מייל ושינויי GitHub. הידע המעובד מופרד ממקורות וקלט ממתין ומסודר לפי תובנות, תכונות, עקרונות והקשר טכני.","סוכן פעולה מפעיל זרימות; סוכני קלט וידע מעבדים חומר; סוכן ארגון מעדכן את המבנה. ריפו מאפשר למהנדסים להוסיף קלט ולעבוד עם הכלי שלהם.","בדמו, בלבול ממשק קטן מוצע לתיקון אחרי שאלה ל-PM. בקשת אומדן מורכבות נשלחת קודם ל-PRD כי היא תלויה בלקוח ובאסטרטגיה.","התוצר והחלטת ה-PM חוזרים כקלט למוח המוצר. זו לולאת משוב, לא הדגמה של אימון מודל או אלגוריתם RL מלא.","מגדירים מראש מתי נדרשים מסמך, אישור וביקורת. בתהליך הדוברת משימות קוד יוצרות PR מעל main ונבדקות בידי אדם.","שמירת ריפו אצל הלקוח אינה מבטלת שליחת תוכן למודל. היא מזכירה גילוי עיבוד צד שלישי או אנונימיזציה, ופיילוט צוותי המתאים קליטה ועלות לקצב השינוי."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. בטקסט שסופק מופיעים גוף ההרצאה, הסיכום ושאלות מהקהל. אין כאן אימות מול הווידאו או הוכחה שלא חסרו קטעים באמצע. המונח reinforcement learning נאמר בהרצאה, אך התמלול אינו מפרט אימון חיזוק למודל. אנונימיזציה אינה הוכחה לאי-זיהוי מחדש או לעמידה ברגולציה.","source_basis":"תמלול מלא שסופק (קובץ מקור 5, פריט 5), כולל שאלות וגם תשובות. שם החברה 'Rezonant' כפי שמופיע בתמלול (ייתכן ASR). ההדגמה מוצגת חזותית ורק מתוארת בקול.","lead":"מוח מוצר ב-GitHub שמזין סוכנים: מ-PM מבצע תהליכים ל-PM שמנהל סוכנים","chapters":[{"title":"קוד נפתר, ו-PM הוא הבא","body":["לטענתה קידוד 'פתור במידה מסוימת', והמנהלים מוצאים שמנהלי מוצר נגררים לעבודה היומית כי המהנדסים מהירים מאוד. השאלה המרכזית כעת היא מה בונים ואיך בונים בטעם.","רוב מנהלי המוצר עושים workflows בסיסיים (פירוק לכרטיסים). Rezonant עושה זאת היטב אך היא טוענת שצריך להגיע למה שהפכו אליו מהנדסי תוכנה: מנהלי סוכנים. מזהים פרוסות של עבודת PM שאפשר לבצע אוטונומית מקצה לקצה, ולכן נדרשת מערכת שלומדת את המוצר.","היא מקבילה להתפתחות הקוד: Cursor, Claude Code, ועכשיו OpenClaw למי שאמיץ בהרשאות. אך באוטומציה של PM הנתונים והעבודה פחות עקביים. נדרש אוטומציה של איסוף מידע מלקוחות, Slack ומיילים, ו'מישור בקרה בין אדם לסוכן' (human agent control plane)."],"points":[],"kind":"idea"},{"title":"מרכיבי מוח המוצר","body":["ארבעה רכיבים: קליטה חיה (למשל פגישת לקוח ב-Granola, GitHub כמקור למה שהמוצר עושה, מייל, כרטיסי Linear), מוח שמסנתז לכל הקלטים ייצוג מהיר לסוכנים, workflows מותאמים (למשל לחזור ללקוח אם כרטיס לא ברור, או לשלוח לפיתוח מקצה לקצה אם מוגדר היטב), וקלט אנושי שמחזק את לולאת הלמידה.","הגרף מקשר מושגים ברמות שונות. שלושה סוכנים: סוכן פעולה (מריץ workflows), סוכן קלט/מוח (מעבד ומארגן מחדש), וסוכן ארגוני (הוויקי מתיישן וצוותים משתנים, צריך ארגון מחדש)."],"points":[],"kind":"idea"},{"title":"הדגמה: ריפו המוח","body":["הריפו ב-GitHub (עם אנונימיזציה): inputs שמעובדים מדי יום, sources (נתונים גולמיים, לא נשמרים כולם כי עלולים להציף את הסוכן), ו-wiki עם תובנות לקוחות, פיצ'רים, עקרונות מוצר (טעם ועקביות) והקשר טכני (זרימות פרונט). הריצה היומית עיבדה כרטיסי Linear, סשן Granola ו-GitHub diffs, ועדכנה קבצי הקשר.","דוגמה לסינתזה שהוצגה: אימות JIRA עבר מתחום-צוות לתחום OAuth, והמערכת ביטאה זאת בצורה שניתנת לשימוש עתידי."],"points":[],"kind":"idea"},{"title":"הדגמה מקצה לקצה","body":["הממשק הראשי הוא Slack ופחות ה-UI. היא יוצרת שני כרטיסי Linear כאילו דווחו על ידי לקוח. הראשון: בלבול סביב 'product charter' בדף הבית. השני: בקשה להעריך את גודל המשימה לפני שהסוכן מתחיל (story pointing).","הסוכן הגיב אחרת לכל אחד. בראשון (היא מודה שרימתה קצת בהכנה כדי שיהיה מה להראות) הוא סבר שמוגדר מספיק כדי לממש, הציג שתי אפשרויות (תיקון צר או שילוב בעבודת האונבורדינג של עמית), וכשבחרה בתיקון הצר יצר משימה ושלח לסוכן קוד ו-PR. אמרה שכאן ירצו מהנדס שיבדוק.","בשני הוא לא המליץ ישר על קוד אלא על כתיבת PRD: אסטרטגית זה כן, אך חופף עבודה אחרת, ומורכבות משימה היא אינדיבידואלית ללקוח. נוצר PRD קצר. בסוף העבודה חוזרת כקלט למוח, ואז הריצה הבאה משפרת את החשיבה. 'מחזור מלא'."],"points":[],"kind":"idea"},{"title":"בנייה עצמית ופרטיות","body":["אפשר לבנות זאת עצמכם; הריפו ב-GitHub כדי שמהנדסים יוסיפו קלט (תיקיית manual) ויעבדו עם כל סוכן קוד. היא מציינת ש-OpenClaw מכיל רעיונות דומים, אבל ההגדרה של פרטיות, מחברי MCP וארגון לצוותים היא מומחיות שנצברה עם שותפים לעיצוב."],"points":[],"kind":"idea"},{"title":"שאלות ותשובות","body":["פרטיות: הריפו חי בדומיין הלקוח. שליחת שיחות למודלים לאינדוקס דורשת לגלות זאת בהסכם עיבוד צד שלישי או לבצע אנונימיזציה עם מיפוי שהצוות רואה.","מפתחים: אפשר להשתמש בריפו כרגיל או להכניס קלט ידני; אין פתרון אחד, תלוי בשותפים וב-artifacts שלהם. כדי שמסמכים יהיו נגישים לסוכני קוד, Rezonant מעדיפה אותם ב-GitHub על פני Google Docs, אך אפשר גם דרך MCP. סיפורי משתמש שמשתנים: היא אומרת שהמערכת עושה diff של Linear כמו ב-GitHub ומעדכנת את הוויקי עם הפניות לכרטיסים.","כלי PM בעתיד: הכלים יהיו יותר על שמירת אסטרטגיה ועקרונות ופחות על ניהול כרטיסים; כרטיס הופך לפיצ'ר שלם. סביבות רגולטוריות: workflows ניתנים להגדרה, למשל חובת תיעוד לפני קוד, ואישורים מתועדים, אך האם קראו ה-PRD תלוי בחברה.","טשטוש הגבול בין PM למהנדס: שני כיוונים, 'בונה מוצר' מלמטה ו-GM אסטרטגי מלמעלה; היא מנחשת שהכיוון השני (כמו בסטרייפ ובגוגל) יתחזק. בחברה גדולה עם מיליוני שורות: מתחילים בצוות אחד, הקליטה מותאמת לקצב השינוי ולתקציב; 'זו אמנות שרוצים להפוך למדע'. בסוף: המוח יוצר משימות דרך ה-API והסוכן פותח PR על main שנסקר על ידי אדם."],"points":[],"kind":"idea"},{"title":"איפה הנתונים כשפונים למודלים?","body":"הריפו בדומיין הלקוח; שליחה למודלים דורשת הסכם עיבוד או אנונימיזציה.","kind":"qa"},{"title":"האם PM והמהנדס מיטשטשים?","body":"שני כיוונים, ובעיניה הסיכוי הוא יותר PM כ-GM אסטרטגי.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["ה-PM המודרני מנהל סוכנים ושומר על אסטרטגיה ועקרונות.","מוח המוצר חייב להתעדכן אוטומטית כדי שיהיו workflows אוטונומיים.","הדגמה אחת מתוך שתיים הוכנה מראש לדברי הדוברת."],"kind":"idea"}],"diagram":{"kind":"loop","title":"לולאת מוח המוצר","nodes":[{"id":"in","label":"קליטה: פגישות, GitHub, מייל, Linear"},{"id":"br","label":"מוח: ויקי בריפו (לקוחות, פיצ'רים, עקרונות, טכני)"},{"id":"wf","label":"workflow: שאלה, PRD או משימה לסוכן קוד"},{"id":"hu","label":"החלטת אדם ב-Slack"},{"id":"pr","label":"PR לסקירת מהנדס"}],"edges":[{"from":"in","to":"br","label":""},{"from":"br","to":"wf","label":""},{"from":"wf","to":"hu","label":""},{"from":"hu","to":"pr","label":""},{"from":"pr","to":"in","label":"קלט חדש חוזר למוח"}],"caption":"הלולאה נבנתה מתיאור הדובר."},"terms":[{"term":"Product brain","definition":"ריפו שמסנתז קלטי מוצר לוויקי שסוכנים משתמשים בו."},{"term":"Human agent control plane","definition":"הבקרות והאיזונים בין סוכנים ל-PM."},{"term":"סוכן ארגוני","definition":"סוכן שמארגן מחדש את הוויקי כשהצוותים משתנים."}],"gaps":["שם החברה והמוצר מתומללים אוטומטית (Rezonant).","בתמלול הדובר המציג מציין שהכותרת השתנתה; הכותרת כאן מהקובץ.","הממשקים הוצגו חזותית ותוארו רק חלקית.","הטענות על עבודה עם שותפים לעיצוב ועל הפרקטיקה בחברות כמו סטרייפ וגוגל הן דברי הדוברת."],"source_refs":["https://www.youtube.com/watch?v=M6Nhl4zR0uk"]}]);
